"""Interface for AI storytelling copy and visual composition planning."""

import re
from abc import ABC, abstractmethod
from typing import List, Optional
from pydantic import BaseModel, Field, model_validator


class PosterPlan(BaseModel):
    """Creative storytelling plan generated by the LLM for poster rendering."""
    headline: str = Field(..., description="Poetic, cinema-grade hook under 7 words")
    story_quote: Optional[str] = Field(None, description="Profound, evocative reflection under 18 words")
    sub_tagline: Optional[str] = Field(None, description="Clean elegant event mark")
    caption: str = Field(..., description="Rich storytelling social caption with detailed thoughts")
    hashtags: List[str] = Field(default_factory=list)
    image_prompt: str = Field(..., description="Cinematic scene description with natural dark space for copy")
    video_motion_prompt: Optional[str] = Field(None, description="Dynamic neural video action prompt describing physical character movement and living environment")
    accent_keyword: Optional[str] = Field(None, description="Key action verb or word to highlight with brand accent color")
    pill_badge_text: Optional[str] = Field(None, description="Concise value proposition or secondary hook rendered in clean pill badge")
    template_name: str = "cinematic_story"
    suggested_overlay_opacity: float = 0.0
    quote: Optional[str] = None  # Backward compatibility

    @model_validator(mode="after")
    def sync_quotes(self):
        # 1. Resolve candidate from story_quote or quote
        candidate = (self.story_quote or self.quote or "").strip()

        # 2. If LLM didn't return a quote, extract an inspiring reflection from the generated caption
        if not candidate and self.caption:
            lines = [
                s.strip() for s in self.caption.split('\n')
                if len(s.strip()) > 15 and len(s.strip()) < 140 and not s.strip().startswith('#') and not s.strip().startswith('•')
            ]
            if lines:
                candidate = lines[0]

        # 3. If still empty, construct an inspiring reflection from the headline
        if not candidate:
            clean_head = (self.headline or "Celebration").strip()
            candidate = f"Let the inspiring spirit of {clean_head} illuminate your journey."

        clean_candidate = candidate.strip().strip('"\'“”').strip()
        self.story_quote = clean_candidate
        self.quote = clean_candidate
        return self


class AbstractTextGenerator(ABC):
    """Abstract contract for text and poster plan generation."""

    @abstractmethod
    async def generate_poster_plan(
        self,
        prompt: str,
        brand_tone: str,
        banned_words: Optional[List[str]] = None,
    ) -> PosterPlan:
        """Generate storytelling copy, caption, and image prompt from user input."""
        pass
